import XCTest

class ProjectPhoenixUITest: XCTestCase {

    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func testOpenProjectPhoenixAndSendMessage() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        sleep(1)

        // Find and tap the Project Phoenix room
        let projectPhoenixRoom = app.staticTexts["Project Phoenix"]
        XCTAssertTrue(projectPhoenixRoom.exists)
        projectPhoenixRoom.tap()

        sleep(1)

        // Find the message input field and type the message
        let messageField = app.textFields.firstMatch
        if messageField.exists {
            messageField.tap()
            messageField.typeText("status update")

            // Find and tap the send button
            let sendButton = app.buttons["Send"]
            if sendButton.exists {
                sendButton.tap()
            }
        }
    }
}
